import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../styles/ViewSales.css";

const ViewSales = () => {
  const userId = sessionStorage.getItem("userId");
  const [mySales, setMySales] = useState([]);
  const [payoutTotal, setPayoutTotal] = useState(0);
  const [paidAmount, setPaidAmount] = useState(null);

  useEffect(() => {
    const fetchSales = async () => {
      try {
        const res = await fetch(`${API_BASE_URL}/api/orders/seller/${userId}`);
        const sales = await res.json();
        setMySales(sales);

        const total = sales.reduce((sum, sale) => sum + sale.price, 0);
        setPayoutTotal(total);
      } catch (err) {
        console.error("❌ Failed to load seller sales:", err);
      }
    };

    if (userId) fetchSales();
  }, [userId]);

  const handlePayout = () => {
    const payout = (payoutTotal * 0.95).toFixed(2);
    setPaidAmount(payout);
    setPayoutTotal(0);
  };

  return (
    <>
      <Navbar />
      <div className="viewsales-container">
        <h2 className="viewsales-heading">💼 My Sales</h2>

        {mySales.length === 0 ? (
          <p className="viewsales-empty">You haven't made any sales yet.</p>
        ) : (
          <div className="viewsales-list">
            {mySales.map((sale, index) => (
              <div key={index} className="viewsales-card">
                <img src={sale.image} alt={sale.title} className="viewsales-image" />
                <div className="viewsales-info">
                  <h4>{sale.title}</h4>
                  <p><strong>Listing ID:</strong> #{sale.listing_id}</p>
                  <p><strong>Sold For:</strong> ${sale.price.toFixed(2)}</p>
                  <p><strong>Buyer:</strong> {sale.buyer_name} ({sale.buyer_email})</p>
                  <p><strong>Delivery ETA:</strong> {new Date(sale.delivery).toLocaleDateString()}</p>
                </div>
              </div>
            ))}
          </div>
        )}

        <div className="viewsales-payout">
          <h3>Total Pending Payout: <span>${payoutTotal.toFixed(2)}</span></h3>
          {payoutTotal > 0 && (
            <button onClick={handlePayout} className="viewsales-payout-btn">
              💸 Payout Now (5% Fee)
            </button>
          )}
          {paidAmount && (
            <div className="viewsales-paid-alert">
              ✅ You got paid: <strong>${paidAmount}</strong>
            </div>
          )}
        </div>
      </div>
      <Footer />
    </>
  );
};

export default ViewSales;
